<?php use App\Core\Html as H; use App\Core\Money; $types=['reserva'=>'Reserva de emergência','viagem'=>'Viagem','imovel'=>'Imóvel','educacao'=>'Educação','outro'=>'Outro']; ?>
<div class="page-heading"><div><p class="eyebrow">DÊ NOME AO SEU FUTURO</p><h1>Objetivos financeiros</h1><p class="text-secondary">Veja o que falta, quanto guardar por mês e acompanhe cada avanço.</p></div><a class="btn btn-uai-primary" href="#nova-meta">+ Novo objetivo</a></div>
<div class="row g-4"><div class="col-xl-7"><section class="card h-100"><div class="card-body"><div class="section-heading"><h2 class="h4">Suas metas</h2><span class="small text-secondary"><?= count($goals) ?> ativa(s)</span></div><?php if(!$goals): ?><div class="empty-state"><h3 class="h5">Qual futuro você quer financiar?</h3><p>Comece com uma reserva, uma viagem ou qualquer objetivo que torne o planejamento concreto.</p></div><?php endif; ?><?php foreach($goals as $goal): $target=(int)$goal['valor_meta_centavos'];$current=(int)$goal['valor_atual_centavos'];$remaining=max(0,$target-$current);$months=null;if($goal['data_alvo']&&$goal['data_alvo']>=date('Y-m-d')){$months=max(1,(int)ceil((strtotime($goal['data_alvo'])-strtotime(date('Y-m-d')))/2629800));} ?><article class="goal-row"><div class="d-flex justify-content-between gap-3"><div><strong><?=H::escape($goal['nome'])?></strong><small><?=H::escape($types[$goal['tipo']]??'Outro')?><?= $goal['data_alvo']?' · até '.H::date($goal['data_alvo']):'' ?></small></div><strong><?=Money::format($current)?></strong></div><progress class="uai-progress success mt-3" max="<?=$target?>" value="<?=min($current,$target)?>" aria-label="Progresso de <?=H::escape($goal['nome'])?>"></progress><div class="goal-meta"><span><?=number_format(min(100,$current/$target*100),1,',','.')?>% concluído · faltam <?=Money::format($remaining)?></span><?php if($months): ?><strong><?=Money::format((int)ceil($remaining/$months))?>/mês por <?= $months ?> mês(es)</strong><?php endif; ?></div><details class="mt-3"><summary class="small">Atualizar progresso</summary><form method="post" class="d-flex gap-2 mt-2" action="<?=H::escape($basePath.'/objetivos/'.$goal['id'].'/progresso')?>"><?=H::fields($csrfToken)?><label class="visually-hidden" for="goal-<?=$goal['id']?>">Valor atual</label><input id="goal-<?=$goal['id']?>" name="valor_atual" class="form-control form-control-sm" inputmode="decimal" required value="<?=H::escape(number_format($current/100,2,',',''))?>"><button class="btn btn-sm btn-uai-primary">Salvar</button></form></details><form method="post" class="mt-2" action="<?=H::escape($basePath.'/objetivos/'.$goal['id'].'/arquivar')?>"><?=H::fields($csrfToken)?><button class="btn btn-sm btn-outline-secondary">Arquivar</button></form></article><?php endforeach;?></div></section></div><div class="col-xl-5"><section class="card" id="nova-meta"><div class="card-body"><h2 class="h4">Criar objetivo</h2><form method="post" action="<?=H::escape($basePath.'/objetivos')?>" class="vstack gap-3"><?=H::fields($csrfToken)?><div><label for="goal-name" class="form-label">Nome</label><input id="goal-name" name="nome" class="form-control" required placeholder="Ex.: Reserva de emergência"></div><div class="row g-3"><div class="col-sm-6"><label for="goal-type" class="form-label">Tipo</label><select id="goal-type" name="tipo" class="form-select" required><option value="">Selecione</option><?php foreach($types as $key=>$label):?><option value="<?=H::escape($key)?>"><?=H::escape($label)?></option><?php endforeach;?></select></div><div class="col-sm-6"><label for="goal-date" class="form-label">Data-alvo</label><input id="goal-date" name="data_alvo" class="form-control" type="date"></div></div><div class="row g-3"><div class="col-sm-6"><label for="goal-target" class="form-label">Meta (R$)</label><input id="goal-target" name="valor_meta" class="form-control" inputmode="decimal" required></div><div class="col-sm-6"><label for="goal-current" class="form-label">Já tenho (R$)</label><input id="goal-current" name="valor_atual" class="form-control" inputmode="decimal" value="0" required></div></div><button class="btn btn-uai-primary">Salvar objetivo</button></form></div></section></div></div>
